package com.universalplatform.assignment;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="assignment_rubric") class Rubric { @Id UUID id; @Column(nullable=false) UUID tenantId; @Column(nullable=false) UUID assignmentId; @Column(nullable=false,length=200) String title; @Column(nullable=false,columnDefinition="text") String criteriaJson; @Column(nullable=false) Instant createdAt; @Version @Column(nullable=false) long version; protected Rubric(){} Rubric(UUID id,UUID tenantId,UUID assignmentId,String title,String criteriaJson,Instant createdAt){this.id=id;this.tenantId=tenantId;this.assignmentId=assignmentId;this.title=title;this.criteriaJson=criteriaJson;this.createdAt=createdAt;} UUID id(){return id;} UUID tenantId(){return tenantId;} UUID assignmentId(){return assignmentId;} String title(){return title;} String criteriaJson(){return criteriaJson;} Instant createdAt(){return createdAt;} long version(){return version;} }
